content:
{
  "generation_request": {
    "meta_data": {
      "tool": "NanoBanana Pro",
      "task_type": "photoreal_cinematic_carousel_couple_close_scene",
      "version": "v1.0_CAROUSEL_RIDE_ROMCOM_WARM_LIGHTS_POSE_LOCK",
      "priority": "highest"
    },
    "references": {
      "female_reference_image": {
        "slot": 1,
        "purpose": "FEMALE_IDENTITY_LOCK",
        "strict_identity_lock": true,
        "no_beautify": true
      },
      "male_reference_image": {
        "slot": 2,
        "purpose": "MALE_IDENTITY_LOCK",
        "strict_identity_lock": true,
        "no_beautify": true
      },
      "composition_reference_image": {
        "source": "UPLOAD_REFERENCE_IMAGE (OPTIONAL)",
        "purpose": "EXACT_COMPOSITION_LIGHTING_WARDROBE_ENV_LOCK",
        "strict_lock": true,
        "no_layout_drift": true,
        "preserve_framing": true
      }
    },
    "output_settings": {
      "aspect_ratio": "4:5",
      "orientation": "portrait",
      "resolution": "ultra_high_res",
      "render_style": "ultra_photoreal_cinematic_lifestyle",
      "sharpness": "crisp_faces_natural_texture",
      "film_grain": "subtle_analog",
      "color_grade": "warm_carnival_golden"
    },
    "hard_constraints": [
      "Chỉ có đúng 2 người (một nữ, một nam).",
      "Khuôn mặt phải khớp với ảnh tham chiếu đã tải lên với độ tương đồng tối đa (không biến dạng, không lệch nhận dạng).",
      "Chỉ ảnh chân thực: kết cấu da tự nhiên, không dùng bộ lọc làm đẹp, không làm mịn da nhân tạo.",
      "Bối cảnh vòng quay ngựa gỗ: trần nhà trang trí công phu có thể nhìn thấy + bóng đèn ấm áp + cột vòng quay ngựa gỗ + ngựa gỗ được sơn.",
      "Khớp logic tư thế tham chiếu: cặp đôi trên ngựa gỗ, nhìn nhau và mỉm cười.",
      "Không có chữ có thể đọc được, không logo, không hình mờ.",
      "Giải phẫu chính xác: tay nắm cột tự nhiên, tư thế ngồi trên ngựa gỗ thực tế."
    ],
    "camera": {
      "style": "ảnh phong cách điện ảnh",
      "lens": "35mm",
      "aperture": "f/2.0",
      "focus": "sắc nét trên cả hai khuôn mặt, làm mờ nhẹ nhàng hậu cảnh",
      "shutter_speed": "1/125",
      "iso": 800,
      "white_balance": "warm_tungsten_carnival"
    },
    "lighting": {
      "type": "bóng đèn vòng quay ngựa gỗ + ánh sáng xung quanh ấm áp",
      "contrast": "trung bình",
      "highlights": "ánh sáng phản chiếu mềm mại trên tóc và vải denim, kiểm soát trên da",
      "shadows": "mềm mại, chuyển tiếp tự nhiên"
    },
    "prompt": {
      "scene_summary": "Cảnh phim lãng mạn hài hước siêu chân thực, đậm chất điện ảnh trên vòng quay ngựa gỗ trong nhà vào ban đêm. Trần vòng quay ngựa gỗ trang trí công phu chiếm phần trên của khung hình với các chi tiết trang trí cổ điển và hàng bóng đèn phát sáng ấm áp. Ở tiền cảnh, đầu ngựa gỗ và cột vòng quay ngựa gỗ có thể nhìn thấy, với các chi tiết cổ điển phong phú (viền vàng, điểm nhấn yên ngựa đầy màu sắc). \n\nChỉ có hai người: người nam ngồi thấp hơn một chút trên ngựa gỗ, hai tay nắm cột dọc và nhìn lên người nữ với nụ cười dịu dàng. Người nữ ngồi trên con ngựa kế bên, hơi nghiêng về phía anh ấy, mỉm cười đáp lại một cách ấm áp. Khuôn mặt của họ là"
    }
  }
}

{
  "scene_overview": {
    "setting": "Nội thất đá kiểu Gothic giống bối cảnh nhà thờ hoặc thánh đường",
    "environment_style": "Mô hình LEGO thu nhỏ",
    "location_type": "Trường quay / sản xuất phim hậu trường",
    "time_of_day": "Trong nhà, ánh sáng được kiểm soát (tâm trạng đêm điện ảnh)",
    "atmosphere": "Điện ảnh, kỳ quái, sân khấu, được kiểm soát",
    "mood": "Hài hước đen tối, ma quái, vui tươi, sáng tạo",
    "genre_influence": ["Kinh dị", "Làm phim hậu trường", "Kỳ ảo"]
  },

  "primary_subject": {
    "type": "Nhân vật LEGO minifigure",
    "role": "Nữ tu / nhân vật kinh dị",
    "appearance": {
      "outfit": "Áo nữ tu đen với cổ áo trắng",
      "face": "Mặt trắng bệch, mắt trũng đen, biểu cảm kỳ quái",
      "accessories": "Dây chuyền thánh giá",
      "pose": "Đứng yên, đối diện về phía trước"
    },
    "positioning": {
      "location": "Nằm ở trung tâm trong một vòm đá lớn",
      "background": "Hốc hoặc buồng được chiếu sáng màu xanh lam rực rỡ"
    }
  },

  "supporting_characters": {
    "crew_members": [
      {
        "role": "Người quay phim",
        "object_interaction": "Vận hành một máy quay phim LEGO lớn",
        "position": "Phía trước bên trái, ngồi trên xe đẩy máy quay"
      },
      {
        "role": "Người điều khiển micro boom",
        "object_interaction": "Giữ micro boom hướng về phía chủ thể",
        "position": "Phía trên bên trái tiền cảnh"
      },
      {
        "role": "Kỹ thuật viên ánh sáng",
        "object_interaction": "Giữ một tấm phản sáng hình chữ nhật",
        "position": "Bên phải, đặt trên giá đỡ"
      },
      {
        "role": "Người điều khiển bảng vỗ",
        "object_interaction": "Giữ một bảng vỗ",
        "position": "Phía trước trung tâm bên phải"
      },
      {
        "role": "Đạo diễn / Giám sát kịch bản",
        "object_interaction": "Giữ bảng kẹp và giấy tờ",
        "position": "Phía dưới bên phải tiền cảnh"
      }
    ],
    "style": "Tất cả các nhân vật đều là LEGO minifigure với tông màu da vàng và nhiều kiểu tóc khác nhau"
  },

  "props_and_equipment": {
    "film_equipment": [
      "Máy quay phim LEGO",
      "Xe đẩy máy quay trên đường ray",
      "Micro boom có kính chắn gió lông",
      "Tấm phản sáng",
      "Bảng vỗ",
      "Màn hình hiển thị nhân vật nữ tu",
      "Dây cáp cuộn trên sàn"
    ],
    "architectural_elements": [
      "Tường gạch đá",
      "Cửa vòm lớn",
      "Hốc tường lõm",
      "Sàn đá lát gạch"
    ]
  },
  "lighting": {
    "primary_light": "Ánh sáng xanh lục lam mạnh từ phía sau nữ tu",
    "secondary_lighting": "Ánh sáng studio trung tính ấm áp trên đoàn làm phim và tiền cảnh",
    "contrast": "Độ tương phản cao giữa nền xanh lạnh và tông màu tiền cảnh ấm áp",
    "style": "Ánh sáng điện ảnh, kịch tính, lấy cảm hứng kinh dị"
  },

  "color_palette": {
    "dominant_colors": ["Xám đậm", "Đen", "Xanh lục lam"],
    "accent_colors": ["Vàng ấm ("
  }
}
